[279950] = { "робот із реагентами", use="Викликати робота, у якого можна купувати реагенти.\n\nНеобхідно перебувати біля вогнища. Усе табірне спорядження має спільний час відновлення - {1} год.#of {1} hour", en="Reagent Bot" },
[279956] = { "колодязь мани", use="Встановити колодязь мани, який відновлює {1} мани кожні {2} с. Не поєднується з ефектом \"Благословення мудрості\".\n\nНеобхідно перебувати біля вогнища. Усе табірне спорядження має спільний час відновлення - {3} год.#regenerate {1} Mana#every {2} sec#of {3} hour", en="Mana Well" },
[279962] = { "ароматична свічка", use="Запалити ароматичну свічку, яка збільшує інтелект на {1}. Не поєднується з ефектом \"Арканічного інтелекту\".\n\nНеобхідно перебувати біля вогнища. Усе табірне спорядження має спільний час відновлення - {2} год.#gain {1}#of {2} hour", en="Incense Candle" },
[279967] = { "акваріум з рибкою", use="Поставити невеликий акваріум з рибкою, який збільшує характеристики на {1}%. Не поєднується з ефектом \"Благословення королів\".\n\nНеобхідно перебувати біля вогнища. Усе табірне спорядження має спільний час відновлення - {2} год.#gain {1}%#of {2} hour", en="Fish Bowl" },
[279968] = { "набір першої допомоги", use="Розпакувати набір першої допомоги, який збільшує витривалість на {1}. Не поєднується з ефектом \"Слова сили: Стійкість\".\n\nНеобхідно перебувати біля вогнища. Усе табірне спорядження має спільний час відновлення - {2} год.#gain {1}#of {2} hour", en="First Aid Kit" },
[279972] = { "знамено фракції", use="Розгорнути знамено, яке збільшує дух членів Орди на {1}. Не поєднується з ефектом \"Божественного духу\".\n\nНеобхідно перебувати біля вогнища. Усе табірне спорядження має спільний час відновлення - {2} год.#gain {1}#of {2} hour", en="Faction Banner" },
[279973] = { "знамено фракції", use="Розгорнути знамено, яке збільшує дух членів Альянсу на {1}. Не поєднується з ефектом \"Божественного духу\".\n\nНеобхідно перебувати біля вогнища. Усе табірне спорядження має спільний час відновлення - {2} год.#gain {1}#of {2} hour", en="Faction Banner" },
[279976] = { "зачарована лютня", use="Викликати зачаровану лютню, яка збільшує броню на {1}[ та всі характеристики на {1}#and {1} increase to all stats||, всі характеристики на {1}#, {1} increase to all stats||][ та всі види опору на {1}#and {1} increase to all resistances]. Не поєднується з ефектом \"Знака дикої природи\".\n\nНеобхідно перебувати біля вогнища. Усе табірне спорядження має спільний час відновлення - {2} год.#gain {1}#of {2} hour", en="Enchanted Lute" },
[279979] = { "похідний стілець", use="Розкласти похідний стілець, який збільшує на {1}% ймовірність критичного удару всіма закляттями й атаками. Не поєднується з ефектом аури місячного совуха.\n\nНеобхідно перебувати біля вогнища. Усе табірне спорядження має спільний час відновлення - {2} год.#gain {1}%#of {2} hour", en="Camp Chair" },
